/*eslint-disable*/import type{Messages}from"@lingui/core";export const messages=JSON.parse("{\"-C4dIk\":[\"Дошки, які потребують примусового ланцюга, рідкісні й дорогі для пошуку на вимогу, тому Suuudokuuu постачає вбудований корпус, який уже перевірили розв’язувач Dancing Links (точне покриття) і бітмасковий розв’язувач, оцінили за рейтингом і відфільтрували до дощок із примусовими ланцюгами ще до упаковки.\"],\"-Elizp\":[\"Коли перетини стануть автоматичними, перейдіть до <0>збірки важкого судоку для друку</0> — фігури «риба» й «крило». Поверніться до <1>легкого судоку для друку</1> для розминки лише з одинаками або грайте в «Середній» на екрані на <2>сторінці середнього судоку</2>.\"],\"-bYKwe\":[\"Містить Everest (SE 11.9), Platinum Blonde (SE 10.9) і AI Escargot (SE 10.6).\"],\"-iJ7nh\":[[\"clueCount\"],\" підказок із 81 клітинки; розв’язується лише «останньою клітинкою» та відкритими одинаками.\"],\"-vAdwL\":[\"Техніки\"],\"0Ktk6B\":[\"Оновлено <0>\",[\"formattedDate\"],\"</0>\"],\"0L9JZJ\":[\"Скільки головоломок у PDF легкого судоку для друку?\"],\"0MRfHz\":[\"Судоку «Нескінченність»\"],\"0RoXsf\":[\"Чи безкоштовний PDF судоку «Кошмар» для друку?\"],\"0Sy9Gs\":[\"Скільки головоломок у PDF судоку «Пекло» для друку?\"],\"0bpi83\":[\"Збірки судоку для друку за складністю\"],\"0r_rbI\":[\"Чи є в \",[\"SITE_NAME\"],\" реклама?\"],\"0zmlwH\":[\"Завантажити «\",[\"title\"],\"» (PDF)\"],\"18cwop\":[\"<0>Легкий</0> — \",[\"easyClueCount\"],\" підказок; гарантовано потрібен принаймні один прихований одинак і не більше.\"],\"1KnfS2\":[\"Скільки підказок у судоку «Кошмар»?\"],\"1Lvcgc\":[\"Головоломка 1 зі збірки «Кошмар», одна з \",[\"PRINTABLE_BOOKLET_SIZE\"],\" у PDF.\"],\"1SEI1B\":[\"Це найскладніший згенерований рівень Suuudokuuu: SE \",[\"seRatingRange\"],\" за вибіркою з \",[\"sampleSize\"],\" дощок. Кожна з них потребує логіки ланцюгів або розфарбування поверх фігур «риба» й «крило», яких уже вимагає «Важкий».\"],\"1ZWQlV\":[\"Як надрукувати ці головоломки\"],\"1ZluOW\":[\"Чому папір допомагає з ланцюгами\"],\"1aVkEA\":[\"Техніка перетину працює на накладанні одного блока й одного рядка чи стовпця. Вказівна пара або вказівна трійка знаходить цифру, обмежену двома чи трьома клітинками блока, що лежать в одній лінії, й вилучає її з решти цієї лінії; взаємодія блока і лінії — дзеркальне відображення, що працює від лінії до блока. Відкриті й приховані пари — це вхід до міркувань із підмножинами: дві клітинки, що ділять рівно два варіанти, або дві цифри, що вміщуються рівно у двох клітинках групи, у будь-якому разі замикають ці дві клітинки від решти. Жодна з них не ставить цифру напряму — вони лише вилучають варіанти, — але за \",[\"clueCount\"],\" підказок середня головоломка завжди має принаймні одну таку можливість, і зазвичай її досить, щоб за хід-два розблокувати новий відкритий одинак. Рівень обмежений і з іншого боку: нічого з риб, крил чи ланцюгів тут не потрібне, бо дошка, якій це потрібне, переходить до «Важкого».\"],\"27Qok0\":[\"Нічого в рівні не потребує риби, крила чи ланцюга — дошка, якій це потрібне, переходить до «Важкого».\"],\"2Dg4GX\":[\"Наскільки це складно, чесно\"],\"2Lb_CG\":[\"Шукайте приховані одинаки\"],\"2N-XHb\":[\"Судоку для людей похилого віку\"],\"2gnUkr\":[\"Новачок\"],\"2wuXBd\":[\"Спершу перевірте, чи не бракує в якомусь блоці, рядку чи стовпці лише однієї цифри. Якщо вісім із дев’яти клітинок групи вже заповнені, дев’ята клітинка мусить отримати цифру, якої групі ще бракує, — без порівняння варіантів, просто віднімання.\"],\"3-aLmy\":[\"Так. Обидві є в наборі «Нескінченність», разом із Platinum Blonde і Golden Nugget. Кожна гра перетасовує цифри, рядки й стовпці, тож сітка щоразу виглядає інакше, а головоломка лишається тією самою.\"],\"35wRk8\":[\"Це найлегший рівень Suuudokuuu, і генератор це гарантує: дошка потрапляє до «Новачка» лише після того, як її завершив розв’язувач, обмежений «останніми клітинками» та відкритими одинаками. Наша вибірка вимірюється як SE \",[\"seRatingRange\"],\", без відстеження варіантів і без ризику вимушеного вгадування.\"],\"367Cn7\":[\"Яка техніка потрібна для збірки легкого судоку?\"],\"3DJmkH\":[\"Наш рушій технік погоджується, що ці дошки лежать за межами його можливостей. Він знає кожен візерунок із <0>індексу технік</0>, аж до <1/> і <2/>, і все одно не здатен самотужки завершити жодну головоломку «Нескінченності». Це не означає, що потрібне вгадування; це означає, що потрібні довші примусові сітки, ніж реалізує рушій. Підказки типово вимкнені в «Кошмарі», «Пеклі» та «Нескінченності», а налаштування вмикає їх назад, якщо хочете допомоги рушія настільки, наскільки він сягає.\"],\"3SwmIF\":[\"Коли ви починаєте гру «Нескінченність», застосунок вибирає одну з цих головоломок і маскує її. Він перепозначає цифри, перетасовує рядки в межах їхніх смуг, стовпці в межах їхніх стеків, а також самі смуги й стеки, а іноді віддзеркалює сітку відносно діагоналі. Нічого з цього не змінює логіку чи рейтинг, тож Everest, у який ви граєте, і далі Everest, просто він не схожий на картинку нижче.\"],\"3a3AKD\":[\"Чи безкоштовна ця збірка судоку «Новачок» для друку?\"],\"3c-rtT\":[\"Завантажити в App Store\"],\"3l9jCt\":[\"Скільки рівнів складності судоку має Suuudokuuu?\"],\"3m4lq2\":[\"Рибу легко пропустити на екрані, де одночасно видно лише жменьку клітинок, адже візерунок складається з місць однієї цифри одразу в двох, трьох або чотирьох цілих лініях. На повній друкованій сітці можна позначити решту позицій цієї цифри вздовж стовпця й побачити форму просто на аркуші. Крила потребують протилежного погляду — кількох двозначних клітинок, які бачать одна одну в різних частинах сітки, — а обведення їх олівцем робить перетин очевидним. Оскільки обидві родини легко застосувати неправильно в перші кілька разів, варто щоразу звіряти результат зі сторінками відповідей наприкінці, доки форма не стане автоматичною.\"],\"4-X0DJ\":[\"Завантажити в Google Play\"],\"4DuWbm\":[\"<0>Правило рядка.</0> У кожному з дев’яти рядків цифри від 1 до 9 мають зустрічатися рівно по одному разу.\"],\"4EAgIb\":[\"Порожня сітка судоку\"],\"4HAVnv\":[\"Кожна головоломка в цій збірці походить із вбудованого корпусу, який Suuudokuuu перевіряє двома незалежними алгоритмами розв’язування — розв’язувачем Dancing Links (точне покриття) і бітмасковим розв’язувачем на типізованих масивах, — перш ніж його випустити, тож для кожної сітки підтверджено рівно один розв’язок. Корпус бере головоломки з каталогу 17-підказкових проєкту tdoku і зі списку складних головоломок top1465 від magictour, а кожну головоломку під час упаковки корпусу ще й розв’язують логічно та оцінюють за шкалою SE. Лишаються лише дошки, чий найважчий крок — примусовий ланцюг; усе, що піддається ланцюгу, розфарбуванню чи AIC, відкидається, бо ні кількість підказок, ні сам список джерел не гарантують головоломку «Пекла». Кожна з тих, що лишилися, усе одно розв’язується на наших сходах технік без вгадування, тож кожна головоломка тут гарантовано розв’язна логікою, ще до того як ви візьмете олівець.\"],\"4NMPvd\":[\"Які техніки потрібні для важкого судоку?\"],\"4apI84\":[\"Судоку великим друком для друку\"],\"4gZ5Vw\":[\"Безкоштовно та з відкритим кодом за ліцензією \",[\"SITE_LICENSE\"],\". Без реклами, без облікового запису, без стеження в грі — прочитайте, <0>чому</0>, або перегляньте <1>повний вихідний код на GitHub</1>. Apple і логотип Apple є товарними знаками Apple Inc., зареєстрованими в США та інших країнах. App Store є знаком обслуговування Apple Inc. Google Play і логотип Google Play є товарними знаками Google LLC.\"],\"52_TbA\":[\"Перевірка риб і крил на папері\"],\"57DMl6\":[\"Ланцюги складаються? <0>Збірка судоку «Пекло» для друку</0> — останній рівень, де кожна головоломка потребує примусового ланцюга. Поверніться до <1>судоку «Важкий» для друку</1>, де лише риби та крила, або грайте в «Кошмар» на екрані на <2>сторінці судоку «Кошмар»</2>.\"],\"5D6pgW\":[\"Дошка рівня «Легкий» з того самого генератора, що й у застосунку. Грайте просто тут.\"],\"5EmtkG\":[\"Чи безкоштовний PDF судоку «Пекло» для друку?\"],\"5YPKNQ\":[\"Хто оцінював ці головоломки?\"],\"5a2b2H\":[\"Чи це головоломки із 17 підказками?\"],\"5tWoLs\":[\"Вивчайте судоку\"],\"64gfbY\":[\"Грати в судоку «Новачок» зараз\"],\"6JHmjr\":[\"Так. Кожну сітку перевіряють розв’язувач Dancing Links (точне покриття) і бітмасковий розв’язувач перед випуском, і кожна має рівно один розв’язок.\"],\"6Y2zqp\":[\"Чи складне середнє судоку?\"],\"6i2Miv\":[\"У «Кошмарі» лише \",[\"clueCount\"],\" підказок, і саме ця збірка по-справжньому виправдовує друк на папері. Кожну головоломку в ній перевірили розв’язувачем, який уже знає кожну рибу й крило — зокрема <0>Swordfish</0> і <1>XY-Wing</1>, — і залишили лише тому, що він застряг. Завершують їх міркування ланцюгами, а ланцюг набагато легше будувати на папері, де можна позначати ланки олівцем і йти за ними, ніж на тісному екрані. Наша вибірка з \",[\"sampleSize\"],\" дощок оцінює рівень як SE \",[\"seRatingRange\"],\".\"],\"6mE7Xy\":[\"Перетин або пара стають помітними лише тоді, коли бачиш усі решту варіантів у рядку, стовпці чи блоці одразу, тому папір тут справді допомагає більше за екран: пишіть маленькі цифри в кутку кожної порожньої клітинки, а потім шукайте в лінії цифру, замкнену в одному блоці, або дві клітинки, що ділять рівно два варіанти. Жоден із цих візерунків сам не ставить цифру — кожен лише вилучає варіанти, тож будьте готові зробити кілька виключень, перш ніж з’явиться новий відкритий одинак. Робота олівцем, а не ручкою, означає, що помилкову помітку можна стерти без наслідків.\"],\"6pYHox\":[\"<0>Новачок.</0> Розв’язується лише «останньою клітинкою» та відкритими одинаками.\"],\"6tfEbk\":[\"Кожна дошка перевірена двома незалежними алгоритмами розв’язування на те, що має рівно один розв’язок.\"],\"6yBCvI\":[\"Що робить головоломку «Кошмаром»\"],\"6z6usR\":[\"Хочете рекордні головоломки на папері? Завантажте <0>PDF судоку «Нескінченність» для друку</0>. Ще не готові до них? Поверніться до <1>судоку «Пекло»</1>, де кожна дошка потребує примусового ланцюга, але лишається в межах досяжності наших сходів технік. Прочитайте історії Everest і AI Escargot на сторінці <2>найскладніші судоку</2>, порівняйте всі рівні на сторінці <3>«Рівні складності судоку»</3> або поверніться <4>на головну</4>.\"],\"6zwJ5l\":[\"«Легкий» розташований внизу шкали SE (Sudoku Explainer) поруч із «Новачком»: наша вибірка з \",[\"sampleSize\"],\" дощок вимірюється як SE \",[\"seRatingRange\"],\". Обидва рівні мають спільний діапазон, бо SE оцінює прихований одинак у 1.5, нижче за відкритий одинак — 2.3, тож техніка, що визначає «Легкий», за цією шкалою дешевша за ту, що визначає «Новачок». Справді змінюється те, куди треба дивитися: відкритий одинак читається з однієї клітинки, прихований — з усієї групи. Рівень підійде гравцям, які пройшли кілька дошок «Новачок» і хочуть головоломку, на яку йде помітно більше часу.\"],\"75Y3_I\":[\"Чи є AI Escargot у збірці для друку?\"],\"7A3Fmz\":[\"Легший рівень\"],\"7Y8jud\":[\"Грати в важке судоку зараз\"],\"7Z44bB\":[\"Впевнено бачите риби й крила? Перейдіть до <0>збірки судоку «Кошмар» для друку</0> — ланцюги й розфарбування. Поверніться до <1>середнього судоку для друку</1> — лише перетини й підмножини, або грайте в «Важкий» на екрані на <2>сторінці важкого судоку</2>.\"],\"7hktsm\":[\"Перші кроки\"],\"7lhqPv\":[\"Коротко\"],\"7r6sCa\":[\"Розмір тексту\"],\"7z1tpm\":[\"Ні. Режим нотаток у застосунку відстежує варіанти за вас, автоматично оновлює їх, коли ви ставите цифри, і дає скасувати помилку, нічого не стираючи.\"],\"83yMJR\":[\"Тепер кожен рівень від «Новачка» до «Нескінченності» має власний посібник, що докладно показує, чим один рівень відрізняється від наступного: кількість підказок, потрібні техніки та чесна оцінка того, наскільки складний кожен із них. Почніть зі сторінки <0>«Рівні складності судоку»</0> або дивіться, як вони співвідносяться з <1>найскладнішими головоломками</1> з будь-коли опублікованих.\"],\"8GGOmr\":[\"Заповнена сітка відповідає всім трьом правилам одночасно. Саме це перетинання робить судоку розв’язним за допомогою логіки: цифра, яку вже виключили її рядок, стовпець і блок, не має куди подітися — на цьому ґрунтується майже кожна техніка розв’язування. Кожна названа на цьому сайті техніка, від найпростішого одинака до найдовшого ланцюга, — це зрештою лише ефективніший спосіб відстежувати це перетинання одразу в багатьох клітинках, а не в одній.\"],\"8HgdwA\":[[\"mediumClueCount\"],\" підказок; гарантовано зайдете в глухий кут на одинаках і подолаєте його перетинами та підмножинами. Щоб зіграти онлайн, перейдіть на <0>сторінку середнього судоку</0>.\"],\"8bwpsb\":[\"Безкоштовне судоку онлайн означає класичну числову головоломку 9×9 у браузері чи застосунку без покупки, обмежень на встановлення чи платного доступу, а \",[\"SITE_NAME\"],\" — її безкоштовна реалізація з відкритим кодом: сім рівнів складності від «Новачка» до «Нескінченності», посібники з поясненням технік, без реклами та стеження в грі. Розв’язуйте в інтернеті або встановіть застосунок, а серії та статистика збережуться всюди однакові. Повне, перевірюване обґрунтування — у матеріалі <0>чому \",[\"SITE_NAME\"],\" побудовано саме так</0>.\"],\"8hKEc0\":[\"Судоку «Кошмар»: поширені запитання\"],\"8j_b89\":[\"«Кошмар» обмежений AIC — дошка, що опирається й цьому, виходить за межі того, що дають згенеровані рівні.\"],\"8ko6ZU\":[\"<0>Пекло</0> — гарантовано зайдете в глухий кут на AIC і потребуватимете примусового ланцюга; головоломки беруться з вбудованого перевіреного корпусу, а не генеруються під рівень.\"],\"8wCnRb\":[\"Головоломки надруковано точно так, як їх було опубліковано, без перетасування, тож можна порівняти свою сітку з оригіналами, які обговорює сторінка про <0>найскладніші судоку</0>. Вони друкуються по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці з місцем для повного набору олівцевих позначок, які вам знадобляться: на цьому рівні більшість розв’язувачів тримає вписаними всі варіанти й перевіряє ланцюги на окремому аркуші. Завершальні сторінки містять розв’язані сітки, тож можна перевірити довгий ряд міркувань, не доводячи його до кінця.\"],\"92GEeo\":[\"Хочете спершу розім’ятися? <0>Збірка судоку «Пекло» для друку</0> містить головоломки з примусовими ланцюгами: складні, але ще в межах досяжності наших сходів технік. Віддаєте перевагу екрану? Грайте в ті самі рекордні головоломки на <1>сторінці судоку «Нескінченність»</1>, де кожна гра перетасовує сітку, або перегляньте всі збірки на <2>сторінці судоку для друку</2>.\"],\"93EF2k\":[\"Скільки підказок у судоку «Пекло»?\"],\"9AexDe\":[\"Якщо дошку можна розв’язати лише «останньою клітинкою» та відкритими одинаками, її відхиляють як надто легку для цього рівня.\"],\"9COcEj\":[\"Фігури «риба»: X-Wing, Swordfish, Jellyfish та їхні finned- і sashimi-варіанти. Фігури «крило»: XY-Wing, XYZ-Wing і W-Wing.\"],\"9TF92W\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок рівня «Легкий» вимірюється як SE \",[\"seRatingRange\"],\".\"],\"9e_cYH\":[\"Судоку «Новачок»: поширені запитання\"],\"9qTjdv\":[\"Скільки головоломок у PDF середнього судоку для друку?\"],\"9rfjS-\":[[\"PRINTABLE_LARGE_PRINT_PAGE_COUNT\"],\" стор.\"],\"AKA0Xn\":[\"Які техніки потрібні для цієї збірки «Важкий»?\"],\"AV85q_\":[[\"clueCount\"],\" підказок із 81 клітинки; розв’язується від початку до кінця «останньою клітинкою», відкритими й прихованими одинаками.\"],\"AdsNQX\":[\"Так. Наша вибірка оцінює «Пекло» як SE \",[\"hellSeRatingRange\"],\", а кожна головоломка «Нескінченності» має опублікований рейтинг від \",[\"lowestRatingLabel\"],\" до \",[\"highestRatingLabel\"],\". Дошки «Пекла» все ще піддаються нашим сходам технік; дошки «Нескінченності» — ні.\"],\"AfMtNM\":[\"Судоку «Пекло»: поширені запитання\"],\"Ak9Eh5\":[\"Дошка рівня «Важкий» з того самого генератора, що й у застосунку. Грайте просто тут.\"],\"B-pBHn\":[\"Ланцюжок рівнів складності судоку\"],\"BJrGt8\":[\"Рівно одна техніка. Кожну дошку «Новачок» можна завершити «останніми клітинками» та відкритими одинаками; кожну дошку «Легкий» доведено не можна, і їй потрібен принаймні один прихований одинак, щоб вийти з глухого кута.\"],\"BZz12Q\":[\"Друк\"],\"C1_WBQ\":[\"Судоку — це логічна головоломка на сітці 9×9, поділеній на дев’ять блоків 3×3. Мета — заповнити кожну порожню клітинку цифрою від 1 до 9 так, щоб жодна цифра не повторювалася в жодному рядку, стовпці чи блоці. Правильно складене судоку завжди починається з кількох заповнених клітинок — заданих цифр, або підказок — і завжди має рівно один коректний розв’язок, до якого можна дійти самою логікою, без вгадування.\"],\"C4kvBI\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок «Пекла» вимірюється як SE \",[\"seRatingRange\"],\", а найпоширенішим найважчим кроком є <0/>.\"],\"CA7v0X\":[\"У деяких із цих сіток лише \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" заданих цифр, і спершу вони здаються майже порожніми — \",[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок друкуються по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці з великими клітинками, щоб було де вручну відстежувати варіанти вздовж довгого ланцюга. Завершальні сторінки містять розв’язані сітки, що на цьому рівні майже необхідно: перевіряти ланцюг виключень на око повільно, а друкований ключ дає змогу підтвердити кінцевий стан без повторного виведення всього шляху.\"],\"CAD1qm\":[\"Ланцюг іде за чергуванням сильних і слабких зв’язків: він починається з варіанта й міркує далі, доки не доведе виключення чи розміщення незалежно від того, яка гілка виявиться істинною. X-Chain працює з однією цифрою; XY-Chain натомість іде шляхом двозначних клітинок. Просте розфарбування призначає мережі сильних зв’язків однієї цифри два чергових кольори й прибирає кожен варіант, який бачить обидва кольори, а AIC узагальнює всю цю родину, змішуючи цифри й типи клітинок в одному суцільному ланцюгу. «Пекло» починається там, де все це вичерпується. Примусовий ланцюг припускає певний варіант, можливі цифри клітинки або місця цифри в області, простежує всі наслідки й залишає лише те, що справджується в кожній гілці — на сторінках <0>Нішіо</0>, <1>клітинки</1> та <2>примусового ланцюга області</2> розібрано по одному прикладу кожного. Дошка потрапляє до корпусу «Пекла» лише тоді, коли її найважчий крок на оптимальному за рейтингом шляху — примусовий ланцюг, і лише якщо наші сходи все ще здатні її завершити, тож жодна дошка «Пекла» не вимагає вгадувати.\"],\"CLPF0E\":[\"Рейтинги — це значення, які публікують незалежні оцінювачі, а не наші власні вимірювання.\"],\"ChsZzh\":[[\"hardClueCount\"],\" підказок; гарантовано зайдете в глухий кут на підмножинах і подолаєте його фігурами «риба» та «крило». Щоб зіграти онлайн, перейдіть на <0>сторінку важкого судоку</0>.\"],\"DE2rA9\":[\"Підказки та складність\"],\"DE6q1A\":[\"Так, за побудовою. «Кошмар» закінчується на AIC, і жодну дошку «Пекла» не можна розв’язати нічим із дозволеного в «Кошмарі». Наша вибірка оцінює «Пекло» як SE \",[\"hellSeRatingRange\"],\", а «Кошмар» — як SE \",[\"nightmareSeRatingRange\"],\".\"],\"DFi0Zn\":[\"Складніше за будь-що інше в застосунку, і з великим відривом. Наша вибірка з \",[\"sampleSize\"],\" дощок <0>«Пекла»</0> вимірюється як SE \",[\"hellSeRatingRange\"],\"; «Нескінченність» починається з \",[\"lowestRatingLabel\"],\". Рейтинги «Нескінченності» — не наші власні вимірювання. Оцінювач Suuudokuuu оцінює сходи SE лише до примусових ланцюгів і сіток і повідомляє \",[\"SE_RATING_CEILING\"],\" із прапорцем стелі вище цього, тож для цих головоломок ми наводимо цифри, які публікують незалежні оцінювачі, як пояснює <1>посібник із рейтингу складності</1>.\"],\"DIr2XR\":[\"Перетини: вказівна пара, вказівна трійка, взаємодія блока і лінії. Підмножини: відкрита пара, прихована пара.\"],\"DRVEbn\":[\"Судоку «Пекло» для друку: поширені запитання\"],\"DRleO8\":[\"<0>Остання клітинка</0> — найпростіший хід: заповнити останню порожню клітинку в рядку, стовпці чи блоці.\"],\"D_b_9m\":[\"Легке судоку: поширені запитання\"],\"DgPHNt\":[\"Майже риба: рядки чи стовпці вишиковуються як X-Wing або <0>Swordfish</0>, крім одного-двох зайвих варіантів — плавця (fin). Виключення все одно діє, але лише в клітинках, які бачать і рибу, і плавець.\"],\"DjGWF0\":[\"Позначте олівцем усі варіанти для порожніх клітинок, що лишилися, а потім проходьте індекс технік у порядку складності, щоб і далі їх очищати.\"],\"Drd4wO\":[\"Цифра, обмежена двома клітинками одного блока, які також лежать в одному рядку чи стовпці. Її можна вилучити з решти цього рядка чи стовпця, бо одна з цих двох клітинок обов’язково містить її.\"],\"DvhSrh\":[[\"clueCount\"],\" підказок із 81 клітинки; гарантовано потрібен прихований одинак і нічого складнішого.\"],\"E5Cz6q\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок\"],\"ER15gL\":[\"Рекордна головоломка рівня «Нескінченність» з того самого добірного набору, що й у застосунку, але перетасована. Грайте просто тут.\"],\"ETZyJl\":[\"Сім рівнів складності від «Новачка» через «Пекло» до «Нескінченності», найвищий рівень пропонує рекордні головоломки, як-от Everest і AI Escargot\"],\"EYQUVy\":[\"<0>Важкий.</0> Завжди заходить у глухий кут на підмножинах і завжди піддається фігурі «риба» або «крило».\"],\"EYVt4M\":[\"Найбільший розмір тексту\"],\"EyMkmB\":[\"Який найлегший рівень складності судоку?\"],\"F_APxp\":[\"Безкоштовне судоку без інтернету для iOS, Android і вебу\"],\"FfmJIb\":[\"Чи безкоштовний PDF середнього судоку для друку?\"],\"Fgi0TQ\":[\"Жодна головоломка в збірці не потребує риби, крила чи ланцюга.\"],\"Fv02gG\":[\"Наша опублікована вибірка з \",[\"sampleSize\"],\" дощок рівня «Важкий» вимірюється як SE \",[\"seRatingRange\"],\", а найпоширенішим найважчим кроком є <0/> — ці числа безпосередньо вимірює <1>посібник із рейтингу складності судоку</1>, а не припускає. \",[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок друкуються по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці з місцем для позначення варіантів, а розв’язані сітки на завершальних сторінках дають змогу підтвердити, що виключення рибою справді спрацювало.\"],\"G70CkD\":[\"Скільки підказок у середньому судоку?\"],\"GCBW83\":[\"Спершу розв’язуйте найдешевші розміщення: «останні клітинки», потім відкриті одинаки, потім приховані одинаки.\"],\"GOSVU9\":[\"Дошки «Середній» містять \",[\"clueCount\"],\" підказок, і гарантовано зайдете в глухий кут на одинаках та подолаєте його перетином чи підмножиною.\"],\"GRoZ7D\":[\"Судоку «Пекло»\"],\"GU9wm2\":[\"Чи можна користуватися ними на уроках?\"],\"G_3WRn\":[\"Чи працює без інтернету?\"],\"GalvXV\":[\"«Нескінченність» — рівень Suuudokuuu за межами «Пекла»: добірний набір найскладніших судоку з будь-коли опублікованих, рекордних сіток, про які спільнота досі сперечається, — грайте безкоштовно. Кожна дошка «Нескінченності» — відома головоломка з опублікованим рейтингом Sudoku Explainer (SE) щонайменше \",[\"minimumRatingLabel\"],\": Everest Арто Інкали, Platinum Blonde, AI Escargot, Golden Nugget і ще \",[\"additionalPuzzleCount\"],\"; перед випуском перевірено, що розв’язок єдиний. Це ті головоломки, які описує наш посібник про <0>найскладніші судоку</0>; у «Нескінченності» ви їх граєте.\"],\"GeGHUl\":[\"Кожен PDF має формат US Letter і намальований векторними лініями та текстом, тож чітко друкується в будь-якому розмірі. Відкрийте файл і друкуйте в масштабі 100% (не «вмістити на сторінці», бо на деяких принтерах це може спотворити сітку); друкуйте односторонньо, якщо хочете тримати відповіді окремо від головоломок.\"],\"Gfmra_\":[\"Для початку — дошка рівня «Легкий». Грайте просто тут або оберіть у застосунку будь-який із семи рівнів складності.\"],\"Gu8Ueq\":[\"Що робить головоломку «Нескінченністю»\"],\"GzaiWG\":[\"Як грати в судоку: поширені запитання\"],\"H47ltZ\":[\"Як надрукувати ці головоломки?\"],\"HCMGUO\":[\"Чи доводиться колись вгадувати?\"],\"HDn1fw\":[[\"clueCount\"],\" підказок із 81 клітинки; гарантовано потрібна принаймні одна фігура типу «риба» або «крило», складніша за будь-яку підмножину.\"],\"HJEQpI\":[\"Від \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" до \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\". «Пекло» добирає головоломки не за кількістю підказок; дошка підходить, якщо їй потрібен примусовий ланцюг, скільки б заданих цифр у ній не було.\"],\"HPogd9\":[\"Чому для головоломок на основі ланцюгів рекомендовано папір?\"],\"HQCVxF\":[\"Чи підходить рівень «Новачок» для дитини або для того, хто розв’язує вперше?\"],\"HSXkrR\":[\"Правильно складена головоломка завжди має рівно один розв’язок і ніколи не вимагає вгадувати.\"],\"HV3Yoi\":[\"Важке судоку\"],\"Ht078b\":[\"Головоломка 1 зі збірки «Середній», одна з \",[\"PRINTABLE_BOOKLET_SIZE\"],\" у PDF.\"],\"I11j00\":[\"«Кошмар» — експертний рівень Suuudokuuu, те, що більшість інших застосунків назвали б «дуже складним» або «експертним». Дошка «Кошмар» має лише \",[\"clueCount\"],\" підказок із 81 клітинки, і саме на цьому рівні обмежених візерунків уже недостатньо: кожну дошку тут перевірили розв’язувачем, який знає кожну рибу й кожне крило аж до <0>W-Wing</0>, і вона має мітку «Кошмар» лише тому, що він застряг. Щоб її завершити, потрібні міркування ланцюгами — <1>X-Chain</1>, <2>XY-Chain</2>, <3>просте розфарбування</3> та <4>AIC</4>, ланцюг чергових висновків, який узагальнює три попередні.\"],\"I3XIAf\":[\"Віддаєте перевагу екрану? Грайте в Suuudokuuu зараз\"],\"IANVSf\":[\"Ні. Ніде немає реклами й немає стеження в грі; цей вебсайт використовує лише анонімну аналітику сторінок без файлів cookie.\"],\"IB9N-i\":[\"Чим підказка відрізняється від варіанта?\"],\"IFKUNe\":[\"Олівцеві позначки, логіка виключень і вгадування не потрібні для жодної головоломки в збірці.\"],\"IOgWqm\":[\"Завантаження дошки…\"],\"I_WAm2\":[\"Так. Після встановлення \",[\"SITE_NAME\"],\" генерує й розв’язує головоломки повністю на вашому пристрої, тож грає однаково без з’єднання.\"],\"IjDWTu\":[\"Як перевіряють головоломки\"],\"IlAsp5\":[\"З якого рівня складності судоку почати?\"],\"IqBsZ0\":[\"Так. PDF завантажується безкоштовно, без облікового запису й водяних знаків, і містить повний ключ відповідей до кожної головоломки.\"],\"IrAE3z\":[\"Розв’язувач\"],\"Iu83qB\":[\"Головоломка 1 зі збірки «Новачок», одна з \",[\"PRINTABLE_BOOKLET_SIZE\"],\" у PDF.\"],\"JBdo3D\":[\"Рівні складності судоку: поширені запитання\"],\"JJoC7U\":[\"Що робить головоломку важкою\"],\"Jrqsp5\":[\"Складність тут зумовлена технікою, яку потребує кожна дошка, а не кількістю підказок.\"],\"JrrSQM\":[\"Чим судоку «Новачок» відрізняється від «Легкого»?\"],\"Jry7J2\":[\"Дошка рівня «Новачок» з того самого генератора, що й у застосунку. Грайте просто тут.\"],\"KDXdKh\":[\"Дошка рівня «Кошмар» з того самого генератора, що й у застосунку. Грайте просто тут.\"],\"KPuUq2\":[\"Вписуйте варіанти, коли прості клітинки закінчилися\"],\"KQe27c\":[\"Чи включені відповіді?\"],\"KVC9CP\":[\"Збірка судоку «Новачок» для друку — це безкоштовний PDF з головоломками з \",[\"clueCount\"],\" підказками, де кожну порожню клітинку можна заповнити «останньою клітинкою» або відкритим одинаком — цю властивість перевірили для кожної головоломки перед тим, як вона потрапила до PDF. Це збірка для того, хто розв’язує вперше, для класу, що лише вивчає правила, і для всіх, хто хоче головоломку, яка ніколи не вимагає здогадки.\"],\"KiwVTj\":[\"Чи пропонує Suuudokuuu версію цієї збірки великим друком?\"],\"Kmcrz2\":[\"Так. \",[\"SITE_NAME\"],\" безкоштовний і з відкритим кодом, без покупок у застосунку, підписок чи платних рівнів складності.\"],\"L0XezG\":[\"Що робить головоломку «Пеклом»\"],\"L36iW5\":[\"Так. Код Suuudokuuu, зокрема генератор цих головоломок, має відкритий код за ліцензією MIT, і цей сайт не обмежує друк чи поширення PDF — зокрема роздавання на уроці, репетиторському занятті чи в пачці робочих аркушів.\"],\"L3TeBG\":[\"Наскільки складне судоку «Новачок»?\"],\"LBVuWJ\":[\"Судоку «Новачок»\"],\"LDOq68\":[\"Скільки головоломок у PDF судоку «Кошмар» для друку?\"],\"LI4SwS\":[\"Що робить головоломку середньою\"],\"LNoRL7\":[\"<0>Легкий.</0> Додаються приховані одинаки, але відстежувати варіанти все ще не потрібно.\"],\"LfQJwZ\":[\"Обкладинка одразу вказує кількість головоломок і сторінок, далі йдуть \",[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці, тож на одному аркуші вміщується \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" повних сіток. На останніх сторінках у тому самому розташуванні — усі розв’язані сітки, тож щоб перевірити відповідь, не доведеться шукати її в іншому форматі. Увесь файл складається з векторної графіки та стандартного шрифту PDF, тому чітко друкується в будь-якому розмірі, який підтримує принтер. Наша опублікована вибірка з \",[\"sampleSize\"],\" дощок рівня «Легкий» вимірюється як SE \",[\"seRatingRange\"],\" — ці числа безпосередньо вимірює <0>посібник із рейтингу складності судоку</0>, а не припускає.\"],\"LrHydF\":[\"Прочитайте <0>посібник «Як грати»</0> — три правила й покроковий розбір перших ходів — або знайдіть будь-який термін у <1>глосарії судоку</1>, який визначає кожну техніку й кожне слово, що вживають посібники.\"],\"Lxq-zS\":[\"Судоку великим друком\"],\"M1Yfw6\":[\"Принаймні один <0>прихований одинак</0> у кожній головоломці — поверх «останніх клітинок» і відкритих одинаків, які вже використовує рівень «Новачок», і нічого складнішого.\"],\"MLFx1h\":[\"Так. «Легкий» — вихідний рівень для PDF великим друком, у вибірці — \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" головоломок із більшими клітинками для тих, кому потрібно більше місця для запису.\"],\"MREaAq\":[\"Усе, що потрібне для «Середнього», плюс принаймні одна фігура «риба» чи «крило»: X-Wing, Swordfish, Jellyfish, їхні finned- і sashimi-варіанти, XY-Wing, XYZ-Wing або W-Wing. Одна з них потрібна завжди, бо дошка, якій вони не потрібні, оцінюється як «Середній».\"],\"MVYMfh\":[\"Складність судоку\"],\"M_zq3f\":[\"Судоку «Нескінченність» для друку: поширені запитання\"],\"Mz7rRO\":[\"Перевірте, чи в якомусь блоці, рядку або стовпці вже заповнено вісім із дев’яти клітинок, і поставте в порожню клітинку цифру, якої бракує.\"],\"N0hmpU\":[[\"clueCount\"],\" підказок із 81 клітинки — лише на одну менше, ніж у рівні «Середній», тож цей рівень визначається не кількістю підказок, а технікою, яку він вимагає.\"],\"NQTfla\":[\"Судоку «Новачок» для друку: поширені запитання\"],\"NeWjyh\":[\"<0>Новачок</0> — \",[\"newbieClueCount\"],\" підказок; розв’язується лише «останньою клітинкою» та відкритими одинаками.\"],\"NkdmkS\":[\"Які техніки потрібні для цієї збірки «Кошмар»?\"],\"Nq65SI\":[\"Ні. Кількість підказок і складність — окремі факти; див. <0>посібник про судоку з 17 підказками</0>. Ці головоломки складні тому, що кожній потрібен примусовий ланцюг, а не через кількість підказок на початку.\"],\"NuoZju\":[\"Пройшли дошку «Пекла» й хочете ще? <0>Судоку «Нескінченність»</0> пропонує рекордні головоломки — Everest, Platinum Blonde, AI Escargot, — які лежать навіть за межами наших примусових ланцюгів. Ще не готові до ланцюгів? Поверніться до <1>судоку «Кошмар»</1>, яке вимагає тих самих міркувань, але з більшою частиною заповненої сітки. Віддаєте перевагу паперу? Завантажте <2>PDF судоку «Пекло» для друку</2>. Перегляньте <3>індекс технік</3>, особливо X-Chain, XY-Chain, просте розфарбування та AIC, <4>посібник «Як грати»</4>, <5>посібник про судоку з 17 підказками</5>, усі рівні на сторінці <6>«Рівні складності судоку»</6> або поверніться <7>на головну</7>.\"],\"Nyd-0x\":[\"Скільки підказок у важкому судоку?\"],\"NzFVBG\":[\"Чому рибу чи крило легше перевірити на папері?\"],\"OMs2n2\":[\"Готові поєднувати виключення в ланцюги, а не шукати форми? Перейдіть до <0>судоку «Кошмар»</0> або поверніться до <1>середнього судоку</1> із перетинами та підмножинами. Віддаєте перевагу паперу? Завантажте <2>PDF важкого судоку для друку</2>. Перегляньте <3>індекс технік</3>, <4>посібник «Як грати»</4>, усі рівні на сторінці <5>«Рівні складності судоку»</5> або поверніться <6>на головну</6>.\"],\"OubwsB\":[\"Скільки головоломок у PDF судоку «Новачок» для друку?\"],\"P2bU2d\":[\"Що робить головоломку легкою\"],\"P6JVwt\":[\"Рідко. Більшість гравців можуть утримати в голові жменьку варіантів, потрібних прихованому одинаку, але записати їх у завантаженішому рядку ніколи не завадить.\"],\"PDbaU0\":[\"Чи потрібні олівцеві помітки в головоломках «Новачок»?\"],\"PFKt-9\":[\"«Важкий» знижується до \",[\"clueCount\"],\" підказок, і це перша збірка для друку на сайті, де самих підмножин не вистачить до кінця. Кожну головоломку в ній перевірили розв’язувачем, який уже знає кожен перетин і кожну підмножину, і залишили лише тому, що він застряг. Завершує їх риба чи крило: <0>X-Wing</0> та її більші й finned-родичі або одне з двозначних крил.\"],\"PGxh1d\":[\"Що таке finned-риба в судоку?\"],\"PKS4Or\":[\"Чи безкоштовний PDF судоку «Нескінченність» для друку?\"],\"PYziuK\":[\"Ланцюг не має сталої форми й будується ланка за ланкою; відстежувати його легше, записуючи кожну сильну й слабку ланку, ніж прокручуючи маленький екран.\"],\"PZQD8F\":[\"Грати зараз\"],\"Pbm-BS\":[\"Як Suuudokuuu гарантує вимогу рівня до техніки?\"],\"Pg0uLs\":[\"Кожен рівень безкоштовний, без реклами та реєстрації. <0>Зіграйте головоломку зараз</0> на будь-якому з семи рівнів або перегляньте повний опис кількості підказок і потрібних технік на сторінці <1>«Рівні складності судоку»</1>. Вчитеся на папері? Почніть із <2>PDF судоку «Новачок» для друку</2>.\"],\"PgRaz8\":[\"Грати в легке судоку зараз\"],\"PivQ2i\":[\"Дуже. Кожна головоломка набору «Нескінченність» має опублікований рейтинг SE щонайменше \",[\"lowestRatingLabel\"],\", значно вище за все, що дають згенеровані рівні чи корпус «Пекла». Наш оцінювач припиняє оцінювати сходи SE на \",[\"SE_RATING_CEILING\"],\", тож наведені тут цифри походять від незалежних оцінювачів, а наш рушій технік не здатен самотужки завершити жодну з цих сіток. Будьте готові до довгих примусових ланцюгів і сіток, і до того, що одна головоломка займе набагато більше часу, ніж будь-що інше на цьому сайті.\"],\"Pqhtap\":[\"Легкий\"],\"PrxlWP\":[\"Судоку «Легкий» для друку: поширені запитання\"],\"PszyWW\":[\"Як найшвидше вдосконалитися в судоку?\"],\"PzS0uu\":[\"Дошки «Важкий» містять \",[\"clueCount\"],\" підказок, і гарантовано потрібна принаймні одна фігура «риба» чи «крило», складніша за будь-яку підмножину.\"],\"Q5B0cW\":[\"Пекло\"],\"QBE_L9\":[\"<0>Кошмар.</0> Завжди заходить у глухий кут на рибах і крилах та завжди піддається логіці ланцюгів або розфарбування.\"],\"Qo4hE6\":[\"Ланцюг іде за чергуванням сильних і слабких зв’язків між варіантами: він починається з одного кінця й міркує далі, доки два кінці не доведуть виключення незалежно від того, який із них істинний. X-Chain робить це з однією цифрою; XY-Chain натомість іде шляхом двозначних клітинок, змінюючи цифру на кожному кроці. Просте розфарбування призначає мережі сильних зв’язків однієї цифри два чергових кольори й прибирає кожен варіант, який бачить обидва кольори. AIC об’єднує все це в одну техніку, змішуючи цифри й типи зв’язків в одному суцільному ланцюгу. Відмінність від риби чи крила полягає не в тонкощах, а у формі: крило — це фіксоване розташування трьох або чотирьох клітинок, яке вчаться розпізнавати з першого погляду, а ланцюг не має сталого розміру й будується крок за кроком. Рівень «Кошмар» обмежений AIC — усе, що й далі не піддається, виходить за межі того, що дають згенеровані рівні.\"],\"R1g33v\":[\"Без головоломки, лише сітка: одна повносторінкова сітка 9×9, щоб переписати головоломку з книжки чи газети, і друга сторінка з чотирма меншими сітками для швидких практичних аркушів. Зручно вчителям, які готують власні аркуші із завданнями, і всім, хто переписує головоломку, знайдену десь без зручної для друку версії.\"],\"RJUjbN\":[\"Поради щодо розв’язування з олівцевими позначками\"],\"RMq7iB\":[\"Риба розглядає одну цифру одразу в кількох лініях. X-Wing — найменша з них: цифру, обмежену тими самими двома стовпцями у двох рядках, можна вилучити з решти цих стовпців, бо в який би з рядків вона не потрапила, стовпці вже визначені. <0>Swordfish</0> поширює ту саму ідею на три лінії, а Jellyfish — на чотири. Варіанти Finned і Sashimi послаблюють базовий візерунок, допускаючи один зайвий варіант, який усе одно дає менше, але безпечне виключення, якщо його врахувати, — і в нашій вибірці вони спрацьовують набагато частіше за підручникові форми. Крила працюють інакше: XY-Wing поєднує три двозначні клітинки, тож варіант, спільний для двох із них, можна вилучити всюди, де його бачать обидві; XYZ-Wing додає цей варіант і опорній клітинці, а W-Wing з’єднує дві однакові двозначні клітинки сильним зв’язком за однією спільною цифрою. Рівень «Важкий» обмежений W-Wing: дошка, яка й далі не рухається після всіх риб і крил, — це вже «Кошмар», а не «Важкий».\"],\"RRGDQM\":[\"«Новачок» — найлегший із семи рівнів Suuudokuuu; далі за зростанням складності йдуть «Легкий», «Середній», «Важкий», «Кошмар», «Пекло» та «Нескінченність».\"],\"Rj2Y_n\":[\"Найвідоміші сітки Infinity мають власні сторінки: кожну можна зіграти, роздрукувати й переглянути покроковий розв’язок рушія: <0>AI Escargot</0>, <1>Golden Nugget</1>, <2>Platinum Blonde</2>, <3>Everest</3>, <4>Kolk</4> і <5>Silver Plate</5>.\"],\"Rwv4vE\":[\"Примусовий ланцюг на кожній дошці, поверх ланцюгів, розфарбування, риб, крил і підмножин, яких вимагають попередні рівні. X-Chain, XY-Chain, просте розфарбування й AIC заведуть далеко, але не до кінця; зазвичай глухий кут розв’язує <0>примусовий ланцюг Нішіо</0>.\"],\"SPFeoH\":[\"Судоку «Важкий» для друку: поширені запитання\"],\"ScJ9fj\":[\"Політика конфіденційності\"],\"Sg-BY5\":[\"Кількість підказок — це не складність. Це лише вхідні дані: що менше початкових цифр, то менше негайних розміщень, і розв’язувач — людина чи машина — мусить застосувати ширший набір названих технік, перш ніж сітка знову зрушить. Suuudokuuu вилучає цифри з розв’язаної сітки до цільового значення для рівня, перевіряє, що результат усе ще має рівно один розв’язок, а потім робить те, що справді визначає рівень: розв’язує кандидата двічі — спершу сходами технік нижчого рівня, потім власними — і залишає дошку лише тоді, коли перша спроба провалюється, а друга вдається. Дошки, що не пройшли, відкидаються, і генерується нова. Саме тому кожен рівень вище описано як гарантію, а не сподівання. <0>Повний індекс технік</0> перелічує кожен візерунок цих сходів у тому порядку, в якому їх пробує розв’язувач. Навіть в одному діапазоні дві дошки можуть сильно різнитися — наскільки саме, вимірює матеріал <1>підказки та складність</1>.\"],\"Sjq7vw\":[\"Для кожної порожньої клітинки, що лишилася, виключіть усі цифри, які вже є в її рядку, стовпці й блоці. Якщо лишилася рівно одна цифра, поставте її.\"],\"T-6Uzi\":[\"Everest Арто Інкали (2010), 21 задана цифра, опубліковано з рейтингом SE 11.9.\"],\"T5khAF\":[\"Грати в судоку «Пекло» зараз\"],\"T91vKp\":[\"Грати\"],\"TW-b-m\":[\"Ні. Кількість підказок — лише вхідні дані, що підштовхують розв’язувача до ширшого набору технік; справді визначає кожен рівень діапазон технік, який перевіряє генератор. Розрив безпосередньо вимірює <0>посібник «Підказки та складність»</0>.\"],\"T_JQXy\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок рівня «Середній» вимірюється як SE \",[\"seRatingRange\"],\".\"],\"T_R-Qz\":[\"Основна\"],\"TiHBaL\":[\"«Важке судоку» — це рівень складності, що починається від \",[\"clueCount\"],\" підказок із 81 клітинки й визначається тим, чого не здатен завершити розв’язувач лише з підмножинами: кожну дошку рівня пропустили через розв’язувач, обладнаний усіма перетинами та підмножинами аж до <0>прихованої четвірки</0>, і залишили лише тому, що він застряг. Глухий кут розв’язує риба — <1>X-Wing</1>, <2>Swordfish</2>, <3>Jellyfish</3> та їхні <4>finned</4>- і <5>sashimi</5>-варіанти — або крило: <6>XY-Wing</6>, <7>XYZ-Wing</7> і <8>W-Wing</8>.\"],\"TqC0fH\":[[\"clueCount\"],\" підказок із 81 клітинки, і кожну порожню клітинку можна заповнити за допомогою «останньої клітинки» або відкритого одинака.\"],\"U1U2tC\":[\"Скільки підказок у легкому судоку?\"],\"U2AKxD\":[\"Судоку для друку: поширені запитання\"],\"U9wBFD\":[\"«Легкий» залишається в межах логіки лише з одинаками, тож він досі дружній до початківців. Єдина додаткова навичка порівняно з «Новачком» — помітити цифру, яка більше нікуди не підходить у групі.\"],\"UF5_iX\":[\"Типовий розмір тексту\"],\"UILsns\":[\"Вписуйте варіанти в клітинку лише тоді, коли перегляд більше не дає розміщень.\"],\"Umo747\":[\"Олівцеві позначки, логіка виключень і вгадування ніколи не потрібні.\"],\"Uq9L94\":[[\"clueCount\"],\" підказок із 81 клітинки — це значно менше третини сітки.\"],\"UveQZj\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок «Кошмару» вимірюється як SE (Sudoku Explainer) \",[\"seRatingRange\"],\"; найпоширеніший найважчий крок — <0/>. AIC тут — стеля: кожна дошка «Кошмару» піддається йому, а <1>рівень «Пекло»</1> починається саме там, де він закінчується, з дощок, які потребують примусового ланцюга. Деякі з цих дощок «Пекла» мають більше заданих цифр, ніж «Кошмар», — найочевидніше свідчення на сайті, що кількість підказок і складність — різні речі. Виміряні таблиці — в нашому <2>посібнику з рейтингу складності судоку</2>. Якісно тут складність перестає бути питанням швидкості й стає питанням утримання в голові цілого ряду умовиводів без втрати нитки.\"],\"V9j1Oq\":[\"Ні. Кожну дошку рівня перед випуском перевіряють на розв’язність технічними сходами до AIC, тож завершений ланцюг завжди існує — робота в тому, щоб його знайти.\"],\"VHv3Qz\":[\"Головоломки «Нескінченності» мають \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\"–\",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" підказок і перевірені двома незалежними алгоритмами розв’язування на єдиний розв’язок.\"],\"VT7jaN\":[\"Дошка рівня «Пекло» з того самого перевіреного корпусу, що й у застосунку. Грайте просто тут.\"],\"VUJcE0\":[\"Так. Кожну головоломку в збірці можна розв’язати лише «останньою клітинкою» або відкритим одинаком, тож позначати варіанти чи виключати їх ніколи не потрібно.\"],\"Vmq46x\":[\"Коли «останні клітинки» й відкриті одинаки стануть автоматичними, перейдіть до <0>збірки легкого судоку для друку</0>, яка додає рівно одну техніку: прихований одинак. Щоб натомість грати в «Новачок» на екрані, відвідайте <1>сторінку судоку для новачків</1>. Повні сходи технік і виміряні дані, що стоять за цими твердженнями, дивіться в <2>індексі технік</2> та <3>посібнику з рейтингу складності судоку</3>.\"],\"W1nEnp\":[[\"clueCount\"],\" підказок із 81 клітинки — третина сітки заповнена ще до початку гри.\"],\"W8o5ac\":[\"Інші рівні визначаються техніками, які вони вимагають. «Нескінченність» визначається репутацією, виміряною: головоломка потрапляє сюди, лише якщо незалежні оцінювачі опублікували для неї рейтинг SE щонайменше \",[\"minimumRatingLabel\"],\". Більшість із \",[\"infinityCorpusSize\"],\" походить зі знімка 2011 року бази найскладніших головоломок, яку веде спільнота розв’язувачів судоку; решта — названі класичні головоломки, взяті з гілок форумів і публікацій, де вони вперше з’явилися. Перш ніж набір упаковують у застосунок, розв’язувач Dancing Links (точне покриття) і бітмасковий розв’язувач обидва підтверджують, що кожна сітка має рівно один розв’язок.\"],\"W9xBMf\":[\"Новачкам варто починати з рівня «Новачок» і підніматися на один рівень за раз; кожен крок додає рівно одну нову техніку порівняно з попереднім аж до «Важкого». Якщо три основні правила ще незнайомі, спершу прочитайте <0>посібник «Як грати»</0>.\"],\"WB-pGD\":[\"Ця збірка друкує \",[\"PRINTABLE_BOOKLET_SIZE\"],\" найскладніших судоку з будь-коли опублікованих, узятих із рівня «Нескінченність» Suuudokuuu: Everest Арто Інкали, AI Escargot, Platinum Blonde, Golden Nugget та інші рекордні сітки, кожна з опублікованим рейтингом SE (Sudoku Explainer) від \",[\"lowestRatingLabel\"],\" до \",[\"highestRatingLabel\"],\". Кожна має рівно один розв’язок, а розв’язані сітки — наприкінці.\"],\"WG8Ftb\":[\"Скільки підказок у головоломці «Новачок»?\"],\"WTwN7-\":[\"Грати в \",[\"SITE_NAME\"]],\"WmW-Gm\":[\"Місце на аркуші тут важливіше, ніж на легших рівнях, бо перетини й пари працюють завдяки позначкам варіантів на полях. \",[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок друкуються по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці в повному розмірі клітинок, і навколо кожної цифри лишається достатньо місця, щоб олівцем вписати дрібні цифри, на яких ґрунтуються міркування про перетин чи пару. Розв’язані сітки закривають файл, тож можна звірити свої позначки варіантів із підтвердженою відповіддю. Наша опублікована вибірка з \",[\"sampleSize\"],\" дощок рівня «Середній» вимірюється як SE \",[\"seRatingRange\"],\" — ці числа безпосередньо вимірює <0>посібник із рейтингу складності судоку</0>, а не припускає.\"],\"WrhTzj\":[\"Так. Кожна збірка за складністю та набір великим друком містять повні розв’язані сітки на останніх сторінках, згенеровані тим самим розв’язувачем, який перед випуском перевіряє, що в кожної головоломки рівно один розв’язок.\"],\"WwMVff\":[\"Наскільки складне судоку «Кошмар»?\"],\"XGVJW3\":[\"Глосарій судоку\"],\"XORYRH\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок друкуються по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці так, щоб ланцюг, який перетинає всю сітку, зручно вміщувався на одному аркуші. Повні розв’язані сітки закривають збірку, що важливіше тут, ніж на легших рівнях: одне пропущене виключення посеред ланцюга швидко накопичується, а друкований ключ відповідей його виявляє. Виміряний розкид, що стоїть за цими твердженнями, — у <0>посібнику з рейтингу складності судоку</0>.\"],\"XpU6Tm\":[\"Чому «Пекло» використовує фіксований корпус головоломок замість генерування?\"],\"XzG50N\":[\"«Пекло» — найскладніший технічно оцінений рівень Suuudokuuu, те, що більшість конкурентів називає «зловмисним» або «екстремальним». Дошку «Пекла» визначає не те, з якою малою кількістю підказок вона починається, а міркування, яких вона вимагає: жодну дошку «Пекла» не можна завершити жодною технікою, яку дозволяє «Кошмар», тож кожна потребує примусового ланцюга. На відміну від згенерованих рівнів, «Пекло» береться з вбудованого корпусу опублікованих складних головоломок, перевіреного двома незалежними розв’язувачами перед випуском, і кожна дошка все одно розв’язується на наших сходах технік без вгадування. Спершу доведеться застосувати кожен візерунок ланцюгів і розфарбування — <0>X-Chain</0>, <1>XY-Chain</1>, <2>просте розфарбування</2> й <3>AIC</3> — а вже потім примусовий ланцюг розв’яже глухий кут.\"],\"Y3fLpk\":[\"Скільки головоломок у PDF важкого судоку для друку?\"],\"YGCzAJ\":[\"Кожну дошку-кандидата розв’язують двічі: спершу сходами технік нижчого рівня, що мають провалитися, а потім власними сходами, що мають вдатися. Дошки, які не пройшли жоден із тестів, відкидаються й генеруються заново.\"],\"YM-Le2\":[[\"clueCount\"],\" підказок із 81 клітинки; гарантовано потрібна принаймні одна техніка ланцюгів або розфарбування, складніша за будь-яку рибу чи крило.\"],\"Y_LLdr\":[\"Чи безкоштовний PDF легкого судоку для друку?\"],\"Yj1j4Z\":[\"Головоломка 1 зі збірки «Пекло», одна з \",[\"PRINTABLE_BOOKLET_SIZE\"],\" у PDF.\"],\"YjxNca\":[\"Грати в судоку «Нескінченність» зараз\"],\"Z-7bqV\":[\"Важке судоку: поширені запитання\"],\"Z9Mfy1\":[\"Що в збірці\"],\"Z9MhMF\":[\"Що робить головоломку «Новачком»\"],\"ZBT6Lr\":[[\"infinityCorpusSize\"],\" рекордних головоломок із \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\"–\",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" підказками, опублікованих із рейтингом SE від \",[\"lowestRatingLabel\"],\" до \",[\"highestRatingLabel\"],\".\"],\"ZPXer3\":[\"Нотатки та варіанти\"],\"Zm7CE_\":[\"Кожну техніку, яку \",[\"SITE_NAME\"],\" використовує для підказок, задокументовано на прикладі дошки, взятої просто з рушія розв’язування. Почніть із <0>повного індексу технік</0> або перейдіть до одного з перших візерунків, які вивчає більшість гравців.\"],\"ZtZST0\":[\"Кожна головоломка потребує примусового ланцюга й узята з нашого вбудованого перевіреного корпусу «Пекла». Щоб зіграти онлайн, перейдіть на <0>сторінку судоку «Пекло»</0>.\"],\"_4AR-Z\":[[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" стор.\"],\"_YA7YX\":[\"Так, разом з Everest, Platinum Blonde і Golden Nugget. Збірка друкує головоломки так, як їх було опубліковано спочатку.\"],\"_kK7k_\":[\"Чим крило відрізняється від ланцюга?\"],\"_nkVQD\":[\"Жодна головоломка в збірці не потребує ланцюга — вони починаються з рівня «Кошмар».\"],\"_t9fa1\":[\"Що таке судоку «Нескінченність»?\"],\"a3pVqb\":[\"Поширені запитання\"],\"aF08Xt\":[\"Сім. «Новачок», «Легкий», «Середній», «Важкий», «Кошмар» і «Пекло» утворюють сходи технік, кожен рівень визначений кількістю підказок і гарантованим діапазоном технік, а не маркетинговою назвою. Над ними — «Нескінченність», добірний набір рекордних головоломок, дібраних за опублікованим рейтингом.\"],\"aIDRsS\":[\"<0>Середній.</0> Завжди заходить у глухий кут на одинаках і завжди піддається перетинам та підмножинам — вказівним парам, взаємодії блока і лінії, відкритим і прихованим парам аж до четвірок.\"],\"aMv0h8\":[\"Дошка рівня «Середній» з того самого генератора, що й у застосунку. Грайте просто тут.\"],\"aOHWJD\":[\"<0>Відкритий одинак</0> — клітинка, в якій залишився рівно один варіант.\"],\"aQ3vvP\":[[\"nightmareClueCount\"],\" підказок; гарантовано зайдете в глухий кут на крилах і подолаєте його ланцюгами та розфарбуванням. Щоб зіграти онлайн, перейдіть на <0>сторінку судоку «Кошмар»</0>.\"],\"aeZiiA\":[\"Кожна головоломка гарантовано має рівно один розв’язок, вгадувати не потрібно\"],\"agPptk\":[\"Середній\"],\"ajKnoT\":[\"Три правила судоку\"],\"alOHPr\":[\"Готові до того, щоб перетини й підмножини почали щось важити? Перейдіть до <0>збірки середнього судоку для друку</0> або поверніться до <1>судоку «Новачок» для друку</1> для ще м’якшої сітки. Щоб натомість грати в «Легкий» на екрані, відвідайте <2>сторінку легкого судоку</2>.\"],\"bIMckF\":[\"Стандартний PDF уже використовує просторий макет із \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" головоломками на сторінці. Для більших клітинок дивіться <0>збірку легкого судоку для друку</0>, яка також є вихідним рівнем для нашого PDF великим друком.\"],\"bJo3n2\":[\"Поради для судоку\"],\"bLowF0\":[\"Розв’язуємо перші клітинки\"],\"bMqX8c\":[\"Шукайте групи, де не вистачає однієї цифри\"],\"bQP2nt\":[\"Розв’язуєте дошки «Легкий», не вдаючись до прихованого одинака? Поверніться до <0>судоку «Новачок»</0> або перейдіть до <1>середнього судоку</1>, де з’являються перетини й перші пари. Віддаєте перевагу паперу? Завантажте <2>збірку легкого судоку для друку</2> або перегляньте посібник <3>судоку для людей похилого віку</3> про великий друк і комфорт. Дивіться повний <4>індекс технік</4>, посібник <5>«Як грати»</5> або всі рівні на сторінці <6>«Рівні складності судоку»</6>, а також <7>головну</7>.\"],\"bUGU7d\":[\"За розміром і формою. Крило — це фіксований візерунок із трьох або чотирьох клітинок, який вчаться розпізнавати з першого погляду; ланцюг будують ланка за ланкою, і він може бути будь-якої довжини, тому на шкалі SE ланцюги стоять на ціле покоління вище за крила.\"],\"bVG9Tb\":[\"Для друку\"],\"bY8tm0\":[\"Вихідний код на GitHub\"],\"bc8DGE\":[\"Заповніть кожну порожню клітинку цифрою від 1 до 9 так, щоб жодна цифра не повторювалася в рядку, стовпці чи блоці 3×3.\"],\"c38U12\":[\"Що таке вказівна пара?\"],\"c3R2ID\":[\"«Остання клітинка» і відкритий одинак — перші дві стратегії, які рушій розв’язування Suuudokuuu пробує на кожній дошці будь-якої складності, бо їх найдешевше перевірити. Особливість «Новачка» в тому, що рівень визначено як дошки, яким ніколи не потрібне щось інше. Якщо прибрати більше цифр, розв’язувач зрештою застрягне без прихованих одинаків, перетинів чи підмножин, і генератор відкидає такі дошки замість того, щоб називати їх «Новачок». Якщо ви можете подивитися на рядок і назвати єдину цифру, якої в ньому бракує, ви вже маєте всі навички, яких вимагає головоломка «Новачок».\"],\"cK6miM\":[\"Складність\"],\"cVxfVr\":[\"Ні. Обидві техніки, яких потребує головоломка «Новачок», читаються просто з дошки, і саме тому це найшвидші висновки в грі.\"],\"d4hJrp\":[\"Складніший рівень\"],\"d5hiJp\":[\"Чому гравці лишаються\"],\"dKAb7E\":[\"Кожна дошка «Пекла» потребує примусового ланцюга: жодну не можна розв’язати техніками, які дозволяє «Кошмар», аж до AIC.\"],\"dXoieq\":[\"Коротко\"],\"do-_4n\":[\"Принаймні одна риба (<0>X-Wing</0> та її більші й finned-родичі) або одне двозначне крило — поверх усіх перетинів і підмножин, яких уже вимагають легші збірки.\"],\"dvRtE-\":[\"Сім: «Новачок», «Легкий», «Середній», «Важкий», «Кошмар», «Пекло» і «Нескінченність». Головоломки «Пекла» беруться з вбудованого перевіреного корпусу дощок, кожна з яких потребує примусового ланцюга, що виходить за межі будь-чого з «Кошмару», а <0>«Нескінченність»</0> пропонує рекордні головоломки, як-от Everest і AI Escargot.\"],\"dyGlGe\":[\"Набір великим друком використовує ту саму логіку рівня «Легкий», що й збірка вище, але по \",[\"PRINTABLE_LARGE_PRINT_PUZZLES_PER_PAGE\"],\" головоломок на сторінці замість \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\", тож кожна клітинка й цифра друкуються помітно більшими. Він підходить людям зі слабким зором, роздатковим матеріалам для класу, які читають здалеку, і всім, кому стандартна сітка на папері здається тісною. Поради з друку й альтернативу на екрані дивіться на <0>сторінці судоку великим друком</0>, а повний огляд із акцентом на комфорті — у посібнику <1>судоку для людей похилого віку</1>.\"],\"e0NrBM\":[\"Проєкт\"],\"eBV_Xh\":[\"Дошки «Кошмар» містять \",[\"clueCount\"],\" підказок, і гарантовано потрібна принаймні одна техніка ланцюгів чи розфарбування, складніша за будь-яку рибу й крило.\"],\"eJ9n-i\":[\"Нова для вас сама сітка? Почніть із <0>посібника «Як грати»</0> — там три правила й перші розміщення, перш ніж обирати рівень вище.\"],\"eJum-4\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок на \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" сторінках, по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці; розв’язані сітки — наприкінці.\"],\"emFA81\":[\"Судоку «Кошмар» для друку: поширені запитання\"],\"enA4B7\":[\"Чи складніше судоку «Важкий» за «Кошмар»?\"],\"eo2JDj\":[\"Застрягли на головоломці?\"],\"eozBux\":[\"Не обов’язково. Головоломки «Пекла» мають \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\"–\",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" підказок і беруться з вбудованого корпусу, перевіреного двома незалежними алгоритмами розв’язування та відфільтрованого до дощок, що потребують примусового ланцюга, а не генеруються наново під час друку.\"],\"ev-7sc\":[\"Ні. «Важкий» закінчується на W-Wing; «Кошмар» починається там, де зупиняється «Важкий», і сягає ланцюгів чергових висновків. Ці два рівні розділяє межа технік, а не кількість підказок.\"],\"evANQd\":[\"Техніки ланцюгів і розфарбування: X-Chain, XY-Chain, просте розфарбування та AIC.\"],\"f0OFpM\":[\"<0>Пекло.</0> Завжди заходить у глухий кут на ланцюгах і AIC та завжди вимагає примусового ланцюга; головоломки беруться з вбудованого перевіреного корпусу.\"],\"fRl01D\":[\"Судоку для друку\"],\"fUYszb\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок, по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці, із повним ключем відповідей.\"],\"fY_UvT\":[\"Це збірка, яку варто друкувати для короткої щоденної звички, а не для довгого сидіння: вкладіть її в зошит, розв’язуйте по одній сітці, і ніколи не доведеться ні записувати варіант, ні відстежувати пару в рядку. Вона також підходить класу, що вперше знайомиться з правилами: увесь клас може закінчити головоломку за той самий короткий час, і ніхто не застрягне на перетині, якого ще не навчився. Макет із \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці все одно лишає кожну сітку достатньо великою, щоб зручно писати, навіть дитячим почерком, а ключ відповідей наприкінці означає, що вчителю не доведеться самому розв’язувати аркуш, щоб його перевірити.\"],\"fiJRay\":[\"Принаймні одна <0>вказівна пара</0>, <1>взаємодія блока і лінії</1> або відкрита чи прихована пара — поверх одинаків, які вже використовують легші збірки. Ніщо не потребує риби, крила чи ланцюга.\"],\"g4WRV6\":[[\"hellCorpusSize\"],\" перевірених головоломок із \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\"–\",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" підказками з каталогу 17-підказкових tdoku та списку top1465 magictour, а не згенерованих наново.\"],\"g5Fk5U\":[\"Важкий\"],\"gJOrtn\":[\"Рівні складності\"],\"gh-p06\":[[\"clueCount\"],\" підказок із 81 клітинки; гарантовано зайдете в глухий кут на одинаках і подолаєте його перетином або підмножиною.\"],\"gmWGv_\":[\"Ланцюг не має сталої форми, тому розмітка олівцем допомагає тут більше, ніж на легших рівнях.\"],\"gqWp2B\":[\"Ланцюг не має сталої форми: він будується ланка за ланкою, і єдиний спосіб не загубитися — записувати його. На папері можна позначати кожну сильну й слабку ланку, простежувати чергування до іншого кінця й одразу бачити, які клітинки видно з обох кінців. На екрані телефона, який доводиться прокручувати, це справді незручно. Це також збірка, де хибне виключення накопичується найгірше: якщо позначити варіант як вилучений, а він мав залишитися, кожна наступна ланка стає хибною, тож сторінки з відповідями варто сприймати як справжню контрольну точку, а не формальність.\"],\"h4IqRM\":[\"Впевнено помічаєте перетини й підмножини? Перейдіть до <0>судоку «Важкий»</0>, де завжди потрібна риба чи крило, або поверніться до <1>судоку «Легкий»</1>, щоб повторити одинаки. Віддаєте перевагу паперу? Завантажте <2>збірку судоку «Середній» для друку</2>. Перегляньте <3>індекс технік</3>, <4>посібник «Як грати»</4>, усі рівні на сторінці <5>«Рівні складності судоку»</5> або поверніться <6>на головну</6>.\"],\"h6WxWJ\":[\"Добре для спокійного розв’язування\"],\"h7hJl_\":[\"Наскільки складні ці головоломки\"],\"hw66JY\":[\"Головоломка 1 зі збірки «Легкий», одна з \",[\"PRINTABLE_BOOKLET_SIZE\"],\" у PDF.\"],\"i0qMbr\":[\"Головна\"],\"i7-8lN\":[\"Підказки з урахуванням техніки: називають точний візерунок розв’язування, а не просто наступну цифру\"],\"iDOJbu\":[\"Риба охоплює цілі рядки чи стовпці одразу, а це легше простежити, позначивши решту позицій цифри вздовж надрукованого стовпця, ніж прокручуючи екран. Крила потребують протилежного погляду — кількох двозначних клітинок, які видно з першого погляду.\"],\"iEH6te\":[\"<0>Прихований одинак</0> — цифра, яка підходить лише в одну клітинку рядка, стовпця чи блока.\"],\"iggj45\":[\"Наскільки складне легке судоку?\"],\"ippIMU\":[\"Цих додаткових порожніх клітинок порівняно з «Новачком» достатньо, щоб сітка перестала заповнюватися сама лише <0>«останніми клітинками»</0>. Коли очевидні розміщення закінчуються, у головоломці «Легкий» завжди лишається принаймні одна клітинка, де єдиний шлях уперед — міркування прихованого одинака: зіставте цифри, яких бракує в кожній групі, з тим, куди вони ще можуть законно потрапити, замість того щоб читати варіанти просто з однієї клітинки. Рушій технік Suuudokuuu пробує прихований одинак третім, одразу після «останньої клітинки» й <1>відкритого одинака</1>, а головоломка рівня «Легкий» ніколи не потребує більшого: ні вказівних пар, ні підмножин, нічого, що вимагає тримати в голові більше однієї групи одночасно. Розрив між рівнями навмисно малий — завширшки рівно одна техніка.\"],\"iu7tUI\":[\"Навігаційний ланцюжок\"],\"iuw_bf\":[\"Рейтинг складності\"],\"iyTmPq\":[\"Кожна названа техніка — це швидший спосіб відстежувати те саме перетинання рядка, стовпця й блока одразу в багатьох клітинках.\"],\"j2fzAU\":[\"Рейтинги SE — це значення, які публікують незалежні оцінювачі та спільнота розв’язувачів судоку. Власний оцінювач Suuudokuuu повідомляє \",[\"SE_RATING_CEILING\"],\" із прапорцем стелі для всього, що складніше, тож власної цифри для цих головоломок він не видає.\"],\"j2t1NI\":[\"Кожен рівень веде на повну сторінку з живим переглядом головоломки та чесними фактами про складність із нашого <0>посібника з рейтингу складності судоку</0>. Для самого PDF потрібен лише принтер.\"],\"jFRHhT\":[\"<0>Нескінченність</0> — \",[\"infinityCorpusSize\"],\" найскладніших з будь-коли опублікованих головоломок, дібраних за опублікованим рейтингом SE від \",[\"infinityLowestRating\"],\" до \",[\"infinityHighestRating\"],\", а не за набором технік; вони недосяжні для жодної техніки зі сходів.\"],\"jJ8CSk\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок рівня «Важкий» вимірюється як SE \",[\"seRatingRange\"],\".\"],\"jMk3uh\":[\"Не шукайте спершу найважчу клітинку. Почніть із найпростіших розміщень: коли їх прибрано, усі наступні клітинки стають легшими.\"],\"jP5seF\":[\"Вивчайте техніки в порядку складності, а не намагайтеся запам’ятати всі візерунки одразу. <0>Індекс технік судоку</0> перелічує їх від «останньої клітинки» до підмножин, кожну з прикладом розв’язування.\"],\"jmetfY\":[\"Чи потрібні в легких головоломках олівцеві помітки?\"],\"juLzrc\":[\"«Легкий» — перший рівень, де Suuudokuuu очікує справжнього, хоч і м’якого розв’язування. Дошка «Легкий» має \",[\"clueCount\"],\" підказок із 81 клітинки, на кілька менше, ніж «Новачок». «Остання клітинка» й відкриті одинаки досі заповнюють більшу частину сітки, але не всю: принаймні одна клітинка завжди потребує <0>прихованого одинака</0> — коли цифра підходить лише в одну клітинку рядка, стовпця чи блока, хоча в цій клітинці лишаються й інші варіанти. Цей один додатковий візерунок — і є весь крок від «Новачка» до «Легкого», і це гарантія, а не тенденція: дошку, яку може закінчити розв’язувач із «останніх клітинок» і відкритих одинаків, відхиляють як надто легку для рівня, а дошку, якій потрібне щось понад прихований одинак, — як надто важку.\"],\"jwpEc6\":[\"Коли прості розміщення закінчуються, відстежувати варіанти вручну стає необхідно. Варіант (олівцева позначка) — це цифра, яку клітинка ще може законно містити з огляду на те, що вже є в її рядку, стовпці й блоці. Якщо вписати кожен варіант у клітинку — на папері дрібними цифрами в куточку або в режимі нотаток у застосунку, — головоломка, що здавалася застряглою, перетворюється на ту, де видно візерунки: пари, трійки й четвірки варіантів, що повторюються в групі, — саме те, що покликані помічати техніки на кшталт відкритих і прихованих пар. Повний метод для кожного візерунка — в <0>індексі технік судоку</0>, а кожен термін із цих посібників визначено в <1>глосарії судоку</1>.\"],\"kFGAW9\":[\"Чи робить мала кількість підказок ці головоломки складними?\"],\"kV-GNp\":[\"<0>Середній</0> — \",[\"mediumClueCount\"],\" підказок; гарантовано зайдете в глухий кут на одинаках і подолаєте його перетинами та підмножинами.\"],\"kbLXsu\":[\"Відповіді — на останніх сторінках\"],\"kc2u3T\":[\"Викреслюйте варіанти клітинка за клітинкою\"],\"lAIHWp\":[\"<0>Важкий</0> — \",[\"hardClueCount\"],\" підказок; гарантовано зайдете в глухий кут на підмножинах і подолаєте його фігурами «риба» та «крило».\"],\"lDdTS6\":[\"Судоку «Середній» для друку: поширені запитання\"],\"lINilK\":[\"PDF відкривається обкладинкою з кількістю головоломок і сторінок, далі йдуть \",[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці, а завершують усі розв’язані сітки на останніх сторінках, тож відповіді ніколи не стоять поруч із нерозв’язаною головоломкою. Кожну сітку намальовано векторними лініями та стандартним шрифтом PDF Helvetica, тому вона лишається чіткою за будь-якого розміру друку й ніколи не залежить від скану. Наша опублікована вибірка з \",[\"sampleSize\"],\" дощок рівня «Новачок» вимірюється як SE \",[\"seRatingRange\"],\" — ці числа безпосередньо вимірює <0>посібник із рейтингу складності судоку</0>, а не припускає.\"],\"lPXkj-\":[\"Чи можна надрукувати цю збірку «Новачок» великим шрифтом?\"],\"lQAsJI\":[\"<0>Правило стовпця.</0> У кожному з дев’яти стовпців цифри від 1 до 9 мають зустрічатися рівно по одному разу.\"],\"laMpeD\":[\"Кошмар\"],\"llBUQM\":[\"Повністю працює без інтернету після встановлення: на iOS, Android і в вебі\"],\"lxRnL8\":[\"<0>Правило блока.</0> У кожному з дев’яти блоків 3×3 цифри від 1 до 9 мають зустрічатися рівно по одному разу.\"],\"lzXj7Z\":[\"Кожна головоломка в цій збірці потребує примусового ланцюга: жодну не можна завершити техніками, які дозволяє «Кошмар», і кожну взято з нашого вбудованого та незалежно перевіреного корпусу «Пекла», а не згенеровано наново. Наша опублікована вибірка з \",[\"sampleSize\"],\" дощок оцінює рівень як SE \",[\"seRatingRange\"],\", а найпоширенішим найважчим кроком є <0/>. Щоб зрозуміти, чому складними їх робить не кількість підказок, прочитайте <1>посібник про судоку з 17 підказками</1>.\"],\"mDD4iI\":[\"Так, без облікового запису й водяних знаків, а розв’язана сітка кожної головоломки — наприкінці.\"],\"mOCJOb\":[\"Пройшли кілька дощок «Кошмару»? <0>Судоку «Пекло»</0> — останній рівень, де кожна дошка потребує примусового ланцюга. Поверніться до <1>судоку «Важкий»</1>, якщо риби й крила ще даються ненадійно. Віддаєте перевагу паперу? Завантажте <2>збірку судоку «Кошмар» для друку</2>. Перегляньте <3>індекс технік</3>, <4>посібник «Як грати»</4>, усі рівні на сторінці <5>«Рівні складності судоку»</5> або поверніться <6>на головну</6>.\"],\"mVu64h\":[\"Дошки «Новачок» містять \",[\"clueCount\"],\" підказок і гарантовано завершуються лише «останніми клітинками» та відкритими одинаками.\"],\"m_1uBm\":[\"Щоденне судоку\"],\"mbw3Zs\":[\"Які бувають рівні складності?\"],\"mdr9O2\":[[\"PRINTABLE_BLANK_GRID_PAGE_COUNT\"],\" стор.\"],\"mf-vQH\":[[\"newbieClueCount\"],\" підказок; розв’язується лише «останньою клітинкою» та відкритими одинаками. Щоб зіграти онлайн, перейдіть на <0>сторінку судоку для новачків</0>.\"],\"mqvuZQ\":[\"Навчитися розв’язувати\"],\"n8c99d\":[\"Розв’язувач судоку\"],\"ngqvTg\":[\"Посилання на головоломки для обміну та повні відтворення гри для будь-якого розв’язування\"],\"o83Dls\":[\"Дошки «Легкий» містять \",[\"clueCount\"],\" підказок, і гарантовано потрібен принаймні один прихований одинак та нічого складнішого.\"],\"o8ErsC\":[\"Чи може судоку мати два розв’язки?\"],\"oACpQU\":[\"Посібники зі складності\"],\"oF5_MF\":[\"Великий розмір тексту\"],\"oFKMy-\":[\"Ще не готові до ланцюгів на папері? Поверніться до <0>збірки судоку «Кошмар» для друку</0> — ті самі міркування ланцюгами, але з більшою частиною заповненої сітки, або до <1>судоку «Важкий» для друку</1> — риби й крила без ланцюгів, або грайте в «Пекло» на екрані на <2>сторінці судоку «Пекло»</2>, де той самий корпус живить кожну головоломку. Готові до рекордних головоломок? <3>Збірка судоку «Нескінченність» для друку</3> містить Everest, AI Escargot та інші рекордні сітки.\"],\"oH36ji\":[\"Чи мають головоломки «Нескінченність» єдиний розв’язок?\"],\"oQ8R9m\":[\"Чи доводиться вгадувати в головоломках «Кошмар»?\"],\"oSfAuO\":[\"Середнє судоку\"],\"o_ys4H\":[\"Кожна дошка «Новачок» оцінюється за шкалою SE (Sudoku Explainer) у момент створення. Наша опублікована вибірка з \",[\"sampleSize\"],\" дощок «Новачок» вимірюється як SE \",[\"seRatingRange\"],\" — самий низ шкали, що сягає 12, і нижче за те, що більшість діаграм на основі SE взагалі зважується називати. «Новачок» існує, щоб навчити перетину рядка, стовпця й блока, на якому будується кожна наступна техніка, а не щоб його перевіряти. Виміряний діапазон для цього й кожного іншого рівня опубліковано в нашому <0>посібнику з рейтингу складності судоку</0>. Швидке розв’язання «Новачка» без помилок — це підтвердження, що ви готові до «Легкого», а не позначка, за якою варто ганятися заради неї самої.\"],\"oc75Be\":[\"Правильно складене судоку — ніколи. Якщо в головоломки більше одного коректного розв’язку, її вважають несправною, бо логіка вже не може вказати єдину відповідь.\"],\"ohi_6A\":[\"Для кожної групи з кількома порожніми клітинками перевірте, чи цифра, якої в групі ще немає, підходить лише в одну з них, навіть якщо в цій клітинці є й інші варіанти.\"],\"p6O9l-\":[\"Скільки головоломок у PDF судоку «Нескінченність» для друку?\"],\"p95wx0\":[\"«Остання клітинка» й одинаки як основа, плюс вказівні пари, вказівні трійки, взаємодія блока і лінії та відкриті чи приховані підмножини аж до четвірок, коли одинаки закінчуються. Принаймні одна з них потрібна завжди, і ніколи не потрібне нічого складнішого.\"],\"pDFJMU\":[\"Завантажте PDF і відкрийте його в будь-якій програмі для перегляду PDF, а потім друкуйте в масштабі 100% на папері US Letter. Кожну сітку намальовано векторними лініями та стандартними шрифтами PDF, тож нічого не потрібно растеризувати, і якість не втрачається за жодного розміру друку.\"],\"pIksP6\":[\"Судоку «Нескінченність»: поширені запитання\"],\"pN5c2M\":[\"Судоку «Кошмар»\"],\"pOHwnD\":[\"Які техніки потрібні для цієї збірки «Середній»?\"],\"pXows4\":[\"У Suuudokuuu сім рівнів складності: шість, кожен з яких вимагає ширшого набору технік за попередній, і «Нескінченність».\"],\"pe908p\":[\"Підказка (або задана цифра) — це цифра, надрукована на дошці до початку гри. Варіант (кандидат) — це цифра, яку ви ще розглядаєте для порожньої клітинки з огляду на те, що наразі виключають її рядок, стовпець і блок.\"],\"plp0e4\":[\"Грати в судоку «Кошмар» зараз\"],\"pu3rE1\":[\"За \",[\"clueCount\"],\" підказок із 81 клітинки ця збірка — перша, яку варто розв’язувати олівцем. Одинаки проводять сітку «Середній» лише частину шляху, але кожна головоломка в ній доведено застрягає на них — саме цей тест кожна дошка мусила провалити, щоб потрапити сюди, — доки ви не помітите <0>вказівну пару</0> чи <1>взаємодію блока і лінії</1>: перетин блока й лінії, який лише вилучає варіанти й ніколи не ставить цифру напряму. Жодна головоломка в збірці не потребує риби, крила чи ланцюга.\"],\"q7QiGX\":[\"Як грати\"],\"qcBjCp\":[\"<0>Кошмар</0> — \",[\"nightmareClueCount\"],\" підказок; гарантовано зайдете в глухий кут на крилах і подолаєте його ланцюгами та розфарбуванням.\"],\"qiqtfW\":[\"Грати в середнє судоку зараз\"],\"qrmik6\":[[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" головоломок\"],\"qwJuVW\":[\"Підвал сайту\"],\"qyiPQ_\":[\"«Легкий» — це збірка, до якої беруться, коли хочуть розв’язати головоломку, не напружуючись: у потязі, за кавою чи перед сном. Кожен висновок досі читається з самої дошки, а не з сітки варіантів, тож писати варіанти на берегах майже не доводиться; прихований одинак вимагає оглянути всю групу, а не одну клітинку, — це зміна звички, а не складності. Тому її зручно друкувати кількома примірниками й розв’язувати невеликий стос протягом тижня, адже жодна головоломка не вимагає такої концентрації, як «Середній» чи «Важкий».\"],\"r2FUkM\":[\"Грати в цю головоломку тут\"],\"r4WJmT\":[\"Техніки судоку\"],\"r7ajsb\":[\"Без реклами, облікового запису чи стеження в грі, ні в інтернеті, ні в застосунку\"],\"r8BZnz\":[\"Чи потрібні ручка й папір, щоб розв’язувати судоку?\"],\"rFkWoz\":[\"Ні. Кожну головоломку, яку генерує Suuudokuuu, перевіряють на єдиний розв’язок під час генерації, тож жодна клітинка ніколи не вимагає вгадування, а вбудовані головоломки рівня «Пекло» додатково перехресно перевіряють два незалежні алгоритми — розв’язувач Dancing Links (точне покриття) і бітмасковий розв’язувач — перед випуском. Будь-яка позиція, що здається неоднозначною, просто потребує техніки, яку ви ще не пробували.\"],\"rISE1w\":[\"Які техніки потрібні для середнього судоку?\"],\"rUmdf8\":[\"Чи безкоштовний PDF важкого судоку для друку?\"],\"rUv2wg\":[\"Це також вихідний рівень для PDF великим друком, у вибірці — \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" головоломок.\"],\"rcYOQY\":[\"Принаймні одна техніка ланцюгів або розфарбування — риби рівня <0>Swordfish</0> і крила рівня <1>XY-Wing</1> самі по собі недостатні — поверх усіх риб і крил, яких уже вимагає рівень «Важкий».\"],\"rgh2Sh\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок «Кошмару» вимірюється як SE \",[\"seRatingRange\"],\".\"],\"rhRptr\":[\"Це справжній крок угору від «Легкого», але кожна потрібна техніка все ще працює в межах одного блока чи лінії за раз — довші риби й ланцюги починаються лише з «Важкого» і далі.\"],\"rjZpLn\":[\"Навчання\"],\"rtx2YX\":[[\"easyClueCount\"],\" підказок, і кожна головоломка вимагає принаймні одного прихованого одинака, але не більше. Щоб зіграти онлайн, перейдіть на <0>сторінку легкого судоку</0>.\"],\"sAlGDx\":[\"Безкоштовно, з відкритим кодом, без реклами\"],\"sMgCJW\":[\"Дошку, яка потребує прихованого одинака чи чогось складнішого, відхиляють і генерують заново — вона ніколи не отримає мітку «Новачок».\"],\"sYhvIH\":[\"<0>Нескінченність.</0> Найскладніші судоку з будь-коли опублікованих, такі як Everest і AI Escargot; їх добирають за опублікованим рейтингом, а не за набором технік — див. <1>сторінку «Нескінченність»</1>.\"],\"sf_Uq_\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок рівня «Новачок» вимірюється як SE \",[\"seRatingRange\"],\".\"],\"sgcKNN\":[\"Кожне правило судоку — це по суті одне й те саме обмеження, застосоване до трьох різних видів груп. Вивчіть його раз — і ви вже знаєте всі три правила.\"],\"sjwplg\":[\"Кожна збірка нижче — безкоштовний PDF із судоку для друку, створений із тих самих джерел головоломок, що й у застосунку: його генератор і детектори технік, а для «Пекла» та «Нескінченності» — вбудовані перевірені корпуси. Оберіть складність, щоб отримати збірку з \",[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок і відповідями на останніх сторінках, або візьміть набір великим друком чи порожню сітку судоку. Без реєстрації, без реклами, без водяних знаків.\"],\"ssPRl9\":[\"Найскладніший рівень Suuudokuuu: \",[\"infinityCorpusSize\"],\" найскладніших судоку з будь-коли опублікованих, кожне з опублікованим рейтингом SE від \",[\"minimumRatingLabel\"],\", — грайте безкоштовно й без реклами.\"],\"svA7xQ\":[\"Готові до головоломки, що потребує ще однієї ідеї? Перейдіть до <0>легкого судоку</0>, яке додає прихований одинак до всього наявного тут. Віддаєте перевагу паперу? Завантажте <1>збірку судоку «Новачок» для друку</1> або перегляньте посібник <2>судоку для людей похилого віку</2> про великий друк і комфорт. Перегляньте повний <3>індекс технік</3> чи <4>посібник «Як грати»</4>, або поверніться <5>на головну</5> й подивіться всі сім рівнів на сторінці <6>«Рівні складності судоку»</6>.\"],\"tHJbOh\":[\"Чи «Нескінченність» складніша за «Пекло»?\"],\"tK6SRc\":[\"Кожна головоломка потребує примусового ланцюга й узята з вбудованого та незалежно перевіреного корпусу дошок із \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\"–\",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" підказками.\"],\"tYB68O\":[\"Головоломка 1 зі збірки «Нескінченність», одна з \",[\"PRINTABLE_BOOKLET_SIZE\"],\" у PDF.\"],\"tc4WHX\":[\"Чи завжди менша кількість підказок означає складнішу головоломку?\"],\"thMLRg\":[\"«Важкий» обмежений W-Wing — дошка, що опирається кожній рибі й крилу, оцінюється як «Кошмар».\"],\"uFeI93\":[\"Кожна гра перетасовує сітку, тому знайома рекордна головоломка щоразу виглядає по-новому.\"],\"uJerz5\":[\"Suuudokuuu оцінює свої головоломки за шестирівневими сходами від «Новачка» до «Пекла», і кожен рівень визначають два конкретні факти, а не маркетингова назва: з якою кількістю підказок починається сітка та які названі техніки розв’язування гарантовано потрібні на цьому рівні. Кожна нова дошка також оцінюється за шкалою SE (Sudoku Explainer) у момент створення тим самим відкритим пакетом оцінювання, який використовує <0>посібник із рейтингу складності судоку</0>, щоб опублікувати виміряний діапазон технік і SE кожного рівня сходів нижче. Над сходами стоїть <1>«Нескінченність»</1> — добірний набір рекордних головоломок із рейтингами, які публікують незалежні оцінювачі, бо вони сягають за верх нашої власної шкали.\"],\"uy5vQS\":[\"Введіть або вставте сітку в <0>покроковий розв’язувач судоку</0>, і він назве кожен хід — Hidden Single, Naked Pair, X-Wing — замість того, щоб просто заповнити дошку. Спершу він перевіряє, що в головоломки рівно один розв’язок, і працює повністю у вашому браузері.\"],\"uyJsf6\":[\"Про проєкт\"],\"v1_ToA\":[\"Перетини й пари знаходять, позначаючи всі варіанти в групі, тому в макеті в кожній клітинці залишено місце саме для цих олівцевих позначок.\"],\"vAJFgP\":[\"Добре для першої звички до судоку\"],\"vEHxJQ\":[\"Рівні складності судоку\"],\"vLhN57\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок рівня «Важкий» вимірюється як SE (Sudoku Explainer) \",[\"seRatingRange\"],\" — чітко в діапазоні, який спільнота пов’язує з фігурами «риба» й «крило», і значно нижче території ланцюгів вище 7. Найпоширеніший найважчий крок — <0/>, а найважче, чого досягла будь-яка дошка вибірки, — <1/>. Саме тут звичайні гравці починають тягнутися до підказки: рибу й крила легко описати, але справді важко побачити на живій дошці, тож очікуйте помітно довшого й ретельнішого розв’язування, ніж вимагає «Середній». Повні дані за рівнями дивіться в <2>посібнику з рейтингу складності судоку</2>.\"],\"vNl4Yu\":[\"«Легкий» починається з \",[\"clueCount\"],\" підказок, на шість менше, ніж «Новачок», і додає рівно одну техніку: кожна головоломка в цій збірці потребує принаймні одного <0>прихованого одинака</0> і жодна — нічого складнішого. Саме цей додатковий візерунок робить її збіркою для спокійного розв’язування за кавою, а не навчальним посібником. Це також вихідний рівень для нашого PDF великим друком, у вибірці — \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" головоломок для тих, кому потрібні більші клітинки.\"],\"vXIe7J\":[\"Мова\"],\"vbOpg_\":[\"Чому \",[\"SITE_NAME\"]],\"viJ4-_\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок «Пекла» вимірюється як SE \",[\"hellSeRatingRange\"],\".\"],\"vlNS-q\":[\"«Новачок» — початковий рівень Suuudokuuu, найм’якше знайомство із сіткою. Дошка «Новачок» починається з \",[\"clueCount\"],\" заповнених клітинок із 81. Кожну решту клітинок можна знайти двома найпростішими висновками в грі: <0>останньою клітинкою</0>, коли в групі лишилася остання порожня клітинка, і <1>відкритим одинаком</1>, коли рядок, стовпець і блок клітинки разом уже охоплюють вісім із дев’яти цифр. Це не опис типової дошки «Новачок» — це правило, яке забезпечує генератор: дошка-кандидат приймається як «Новачок» лише після того, як її завершив розв’язувач, обмежений «останніми клітинками» та відкритими одинаками. Олівцеві позначки, логіка виключень і вгадування ніколи не потрібні.\"],\"voLlG5\":[\"З чого почати розв’язування судоку\"],\"vsge_o\":[\"Новачок у судоку?\"],\"vvCT_r\":[\"Куди далі\"],\"vwz0Q4\":[[\"fileSizeKilobytes\"],\" КБ, PDF, US Letter\"],\"wIwe3l\":[\"Як побудовано сходи\"],\"wT9V53\":[\"На рівні «Середній» Suuudokuuu починає вимагати олівцевих позначок. Дошка «Середній» має \",[\"clueCount\"],\" підказок із 81 клітинки, і самі лише одинаки доведено ніколи її не завершують: кожну дошку рівня перевірили розв’язувачем лише з одинаками й відхилили, якщо він упорався. Коли «останні клітинки» й одинаки закінчуються, головоломка стоїть, доки ви не помітите перетин — цифру, обмежену місцем накладання блока й лінії, — або пару, що тримається разом. Перетини охоплюють <0>вказівні пари</0>, <1>вказівні трійки</1> та <2>взаємодію блока і лінії</2>; найменший візерунок підмножин — це <3>відкриті пари</3> та <4>приховані пари</4>.\"],\"xI2Au1\":[\"Головоломка 1 зі збірки «Важкий», одна з \",[\"PRINTABLE_BOOKLET_SIZE\"],\" у PDF.\"],\"xRTkBI\":[\"Нескінченність\"],\"xTziZu\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" головоломок на \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" сторінках, по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці; розв’язані сітки — наприкінці.\"],\"xYaf-9\":[\"Чи «Пекло» складніше за «Кошмар»?\"],\"xkW-Mi\":[\"Чому в цій збірці довкола кожної цифри більше місця?\"],\"xs4NvR\":[\"Чи безкоштовний \",[\"SITE_NAME\"],\"?\"],\"y-GOTe\":[\"Після цього подивіться на одну порожню клітинку й викресліть усі цифри, що вже є в її рядку, стовпці й блоці. Якщо лишилася лише одна цифра, це <0>відкритий одинак</0>, і її можна ставити одразу. Якщо в клітинці лишилося кілька варіантів, перевірте, чи один із них не підходить більше нікуди в тій самій групі — це <1>прихований одинак</1>, і ставити його так само безпечно. Разом ці два візерунки розв’язують більшість легкої головоломки без глибших міркувань.\"],\"yDLr5P\":[\"Судоку великим шрифтом\"],\"yNzy3T\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок рівня «Середній» вимірюється як SE \",[\"seRatingRange\"],\", і \",[\"singlesOnlyPuzzleCount\"],\" із \",[\"sampleSize\"],\" завершилися лише на одинаках — це перший рівень, де це число нульове за побудовою. Найпоширеніший найважчий крок у вибірці — <0/>, а найважче, чого досягли дошки, — <1/>. Гравці, які вільно читають олівцеві позначки, проходять дошку «Середній» помітно швидше за тих, хто покладається на запам’ятовування варіантів, і саме для них це перший рівень, що справді винагороджує записування варіантів. Повні дані за рівнями — в нашому <2>посібнику з рейтингу складності судоку</2>.\"],\"y_3zNL\":[\"«Остання клітинка» й відкриті одинаки досі заповнюють більшу частину сітки; прихований одинак — єдине доповнення порівняно з «Новачком».\"],\"yjTW_5\":[\"Які техніки потрібні для рівня «Пекло»?\"],\"yy8xD2\":[\"Сама сітка ніколи не змінюється: дев’ять рядків, дев’ять стовпців і дев’ять блоків, усього вісімдесят одна клітинка. Від головоломки до головоломки змінюється лише те, які клітинки заповнені спочатку й які цифри в них, і саме цей початковий розклад заданих цифр визначає, скільки логіки потрібно, щоб дійти єдиного коректного розв’язку.\"],\"z0P0h9\":[\"Наша вибірка з \",[\"sampleSize\"],\" дощок «Пекла» вимірюється як SE (Sudoku Explainer) \",[\"hellSeRatingRange\"],\"; найпоширеніший найважчий крок — <0/>, а найважчий крок, якого досягла будь-яка дошка вибірки, — <1/>. Остерігайтеся вважати причиною кількість підказок: та сама вибірка оцінює <2>«Кошмар»</2> як SE \",[\"nightmareSeRatingRange\"],\" із \",[\"nightmareClueCount\"],\" підказками, а деякі дошки «Пекла» починаються з більшої кількості заданих цифр. Раніше цей рівень складався лише з головоломок із 17 підказками, і оцінювався не складніше за «Кошмар»; саме добір за потрібною технікою розділяє ці рівні. Наш <3>посібник «Підказки та складність»</3> докладно розбирає цей аргумент, а <4>посібник із рейтингу</4> публікує таблиці за рівнями.\"],\"zGCYA8\":[\"Чи можна тут зіграти AI Escargot та Everest?\"],\"zX6n8C\":[\"Рекордні головоломки, як-от Everest і AI Escargot, надруковані так, як їх було опубліковано. Щоб зіграти онлайн, перейдіть на <0>сторінку судоку «Нескінченність»</0>.\"],\"zaRGXY\":[\"Порожня сітка судоку\"],\"zdhNJO\":[\"Середнє судоку: поширені запитання\"],\"zu-XZL\":[\"Легке судоку\"],\"zuuvDj\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" рекордних головоломок, по \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" на сторінці, із повним ключем відповідей.\"]}")as Messages;